import random
import math
from fractions import Fraction

def gaussian_elimination(matrix):
    rows, cols = len(matrix), len(matrix[0])
    for i in range(cols):
        pivot_row = None
        for j in range(i, rows):
            if matrix[j][i] != 0:
                pivot_row = j
                break
        if pivot_row is None:
            continue
        for j in range(rows):
            if j == pivot_row:
                continue
            factor = -matrix[j][i] / matrix[pivot_row][i]
            for k in range(i, cols):
                matrix[j][k] += factor * matrix[pivot_row][k]

def min_rank(matrix):
    rows, cols = len(matrix), len(matrix[0])
    rank = 0
    for i in range(cols):
        if all(matrix[j][i] == 0 for j in range(rank)):
            continue
        rank += 1
        gaussian_elimination([matrix[j][i:] for j in range(rank)])
    return rank

def random_cnf(n, m):
    variables = list(range(1, n + 1))
    clauses = []
    for _ in range(m):
        clause = [random.choice(variables) if random.choice([True, False]) else -random.choice(variables) for _ in range(random.randint(2, 3))]
        clauses.append(clause)
    return clauses

def p_adic_diff(formula):
    n = len(formula[0])
    p_adic_diffs = []
    for clause in formula:
        diff = [Fraction(1, 1)]
        for lit in clause:
            if lit > 0:
                diff.append(Fraction(-1, lit))
            else:
                diff.append(Fraction(1, -lit))
        p_adic_diffs.extend(diff)
    return p_adic_diffs

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n = random.choice([5, 10, 15, 20, 30, 40])
    m = 2 * n
